// AppHost/Program.cs
var builder = DistributedApplication.CreateBuilder(args);

// 声明基础设施资源
var postgres = builder.AddPostgres("postgres")
    .AddDatabase("ordersdb");
var redis = builder.AddRedis("cache");
var rabbitmq = builder.AddRabbitMQ("messaging");

// 声明服务并表达依赖
var orderApi = builder.AddProject<Projects.OrderApi>("orderapi")
    .WithReference(postgres)
    .WithReference(redis)
    .WithReference(rabbitmq);

var inventoryApi = builder.AddProject<Projects.InventoryApi>("inventoryapi")
    .WithReference(postgres)
    .WithReference(orderApi);  // 服务对服务的依赖

builder.AddProject<Projects.WebApp>("webapp")
    .WithReference(orderApi)
    .WithReference(inventoryApi);

builder.Build().Run();

// -------------------------------------------------------
// OrderApi/Program.cs —— 服务侧只需声明要用什么
var builder = WebApplication.CreateBuilder(args);

builder.AddRedisClient("cache");           // 集成组件自动读连接串
builder.AddNpgsqlDataSource("ordersdb");   // 集成组件自动读连接串
builder.Services.AddServiceDiscovery();     // 启用服务发现
builder.Services.AddHttpClient<InventoryApiClient>(client =>
{
    client.BaseAddress = new Uri("https://inventoryapi"); // 逻辑名，运行时自动解析
});

var app = builder.Build();
app.MapGet("/orders", async (IDatabase db, InventoryApiClient inventory) =>
{
    // 业务逻辑
});
app.Run();
